<?php
if(!defined('ABSPATH'))exit;
function dgs_study_duration($minutes){$minutes=(int)$minutes;$h=intdiv($minutes,60);$m=$minutes%60;return dgs_fa_digits(($h?$h.' ساعت':'').($h&&$m?' و ':'').($m?$m.' دقیقه':'').(!$h&&!$m?'۰ دقیقه':''));}
function dgs_study_anchor($year){$today=dgs_att_today();return dgs_att_parse_day(dgs_att_jdate($today),$year)===$today?$today:dgs_att_gregorian((int)substr($year,5,4),6,31);}
function dgs_study_week($student,$year,$rolling=false){$day=new DateTimeImmutable(dgs_study_anchor($year),wp_timezone());$start=$rolling?$day->modify('-6 days'):$day->modify('-'.(((int)$day->format('w')+1)%7).' days');$end=$start->modify('+6 days');$days=dgs_study_days($student,$year,$start->format('Y-m-d'),$end->format('Y-m-d'));$names=array('شنبه','یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه');$out=array();for($i=0;$i<7;$i++){$date=$start->modify('+'.$i.' days')->format('Y-m-d');$out[]=array('day'=>$date,'label'=>$names[((int)(new DateTimeImmutable($date))->format('w')+1)%7],'minutes'=>(int)($days[$date]->minutes??0));}return $out;}
function dgs_study_bars($week){$accessible=implode('، ',array_map(function($d){return $d['label'].': '.dgs_study_duration($d['minutes']);},$week));$max=max(300,...array_column($week,'minutes'));$ceiling=(int)(ceil($max/60)*60);$out='<div class="dst-chart" role="img" aria-label="'.esc_attr($accessible).'"><div class="dst-chart-scale">';for($i=5;$i>=0;$i--)$out.='<span>'.esc_html(dgs_school_number($ceiling*$i/300,1)).' ساعت</span>';$out.='</div><div class="dst-bars">';foreach($week as $d){$pct=round($d['minutes']/$ceiling*100,2);$out.='<div class="dst-bar-column"><div class="dst-bar-track"><div class="dst-bar" style="height:'.$pct.'%"><b>'.esc_html(dgs_fa_digits(sprintf('%d:%02d',intdiv($d['minutes'],60),$d['minutes']%60))).'</b></div></div><strong>'.esc_html($d['label']).'</strong><small>'.esc_html(dgs_study_duration($d['minutes'])).'</small></div>';}return $out.'</div></div>';}
function dgs_study_form($op,$year){return '<form class="dge-form dst-form" method="post" action="'.esc_url(admin_url('admin-post.php')).'">'.wp_nonce_field('dgs_study','dgs_study_nonce',true,false).'<input type="hidden" name="action" value="dgs_study"><input type="hidden" name="operation" value="'.esc_attr($op).'"><input type="hidden" name="year" value="'.esc_attr($year).'"><input type="hidden" name="day" value="'.esc_attr(dgs_att_today()).'">';}
function dgs_study_months(){return array(1=>'فروردین',2=>'اردیبهشت',3=>'خرداد',4=>'تیر',5=>'مرداد',6=>'شهریور',7=>'مهر',8=>'آبان',9=>'آذر',10=>'دی',11=>'بهمن',12=>'اسفند');}
function dgs_study_month_history($student,$year){$anchor=dgs_att_jdate(dgs_study_anchor($year));$period=dgs_grade_period(dgs_att_get('study_month'),$year)?:substr($anchor,0,7);$months=array();foreach(explode('-',$year) as $y)for($m=1;$m<=12;$m++){$key=sprintf('%04d-%02d',$y,$m);if(dgs_grade_period($key,$year))$months[$key]=dgs_study_months()[$m].' '.dgs_fa_digits($y);}ksort($months);$out='<section class="dst-card" id="dst-monthly"><div class="dst-section-heading"><div><h3>'.dgs_school_icon('calendar').' تاریخچه مطالعه ماهانه</h3><p>مجموع مطالعه و میانگین در روزهایی که مطالعه ثبت شده است</p></div><form class="dst-month-filter" method="get" action="'.esc_url(dgs_page_url('portal')).'"><input name="dg_tab" value="study" type="hidden"><input name="dg_year" value="'.esc_attr($year).'" type="hidden">'.dgs_edu_select('study_month','ماه',$months,$period).'<button class="dg-btn">نمایش</button></form></div>'.dgs_edu_table_start(array('ماه','تعداد روز ثبت‌شده','مجموع مطالعه','میانگین روزانه'));
 for($i=0;$i<3;$i++){$valid=dgs_grade_period($period,$year);if($valid){$y=(int)substr($period,0,4);$m=(int)substr($period,5,2);$start=dgs_att_gregorian($y,$m,1);$next=$m===12?dgs_att_gregorian($y+1,1,1):dgs_att_gregorian($y,$m+1,1);$end=(new DateTimeImmutable($next))->modify('-1 day')->format('Y-m-d');$rows=dgs_study_days($student,$year,$start,$end);$sum=array_sum(array_map(function($r){return (int)$r->minutes;},$rows));$count=count($rows);$out.='<tr '.($i===0?'class="dst-selected-month"':'').'><td>'.esc_html(dgs_study_months()[$m].' '.dgs_fa_digits($y)).'</td><td>'.esc_html(dgs_fa_digits($count)).' روز</td><td>'.esc_html(dgs_study_duration($sum)).'</td><td>'.esc_html($count?dgs_study_duration((int)round($sum/$count)):'—').'</td></tr>';}$period=dgs_grade_previous($period);}
 return $out.'</tbody></table></div></section>';}
function dgs_study_student($year){
 $uid=get_current_user_id();$today=dgs_att_today();$entries=dgs_study_entries($uid,$year,$today,$today);$edit_id=absint(dgs_att_get('study_edit'));$edit=null;foreach($entries as $a)if((int)$a->id===$edit_id)$edit=$a;$class=dgs_hw_student_class($year);$subjects=$class&&$class->active?dgs_study_subjects($class->id):array();$can_register=dgs_att_parse_day(dgs_att_jdate($today),$year)===$today&&$subjects;$sum=array_sum(array_map(function($r){return (int)$r->minutes;},$entries));$week=dgs_study_week($uid,$year);
 $out='<div class="dsp-school dst-study dst-student">'.dgs_school_title('ثبت مطالعه روزانه','ثبت و مدیریت زمان مطالعه روزانه، مشاهده گزارش‌های هفتگی و ماهانه و پیگیری روند پیشرفت مطالعاتی').'<div class="dst-today">'.dgs_school_icon('calendar').' امروز: '.esc_html(dgs_fa_digits(dgs_att_jdate($today))).'</div><div class="dst-entry-layout"><section class="dst-card dst-entry-card"><h3>'.dgs_school_icon('book').' '.($edit?'ویرایش مطالعه':'ثبت مطالعه جدید').'</h3>';
 if($edit_id&&!$edit)$out.='<p class="dge-error">رکورد انتخاب‌شده متعلق به سوابق امروز شما نیست.</p>';if($can_register){$out.=dgs_study_form($edit?'edit':'create',$year).'<input type="hidden" name="request_token" value="'.esc_attr(wp_generate_uuid4()).'"><input type="hidden" name="entry_id" value="'.($edit?(int)$edit->id:0).'"><input type="hidden" name="revision" value="'.($edit?(int)$edit->revision:0).'"><div class="dst-entry-fields">'.dgs_edu_select('subject_id','درس *',$subjects,$edit?$edit->subject_id:0).dgs_edu_select('hours','ساعت *',array_combine(range(0,24),array_map('dgs_fa_digits',range(0,24))),$edit?intdiv($edit->minutes,60):0).dgs_edu_select('minutes','دقیقه *',array_combine(range(0,59),array_map('dgs_fa_digits',range(0,59))),$edit?$edit->minutes%60:30).'<label>یادداشت (اختیاری)<input name="note" maxlength="1000" value="'.esc_attr($edit?$edit->note:'').'" placeholder="مثلاً تمرین فصل دوم"></label></div><div class="dst-form-actions"><button class="dg-btn">✓ '.($edit?'ذخیره ویرایش':'ثبت مطالعه').'</button>'.($edit?'<a class="dg-btn dg-btn-outline" href="'.esc_url(dgs_edu_url('study',$year)).'">انصراف</a>':'').'</div></form>';}else $out.='<p class="dst-empty">برای ثبت امروز، سال تحصیلی مربوط و کلاس فعال با درس‌های تخصیص‌یافته لازم است. سوابق سال انتخابی قابل مشاهده‌اند.</p>';
 $out.='</section><aside class="dst-today-total">'.dgs_school_icon('clock').'<h3>مجموع مطالعه امروز</h3><strong>'.esc_html(dgs_study_duration($sum)).'</strong></aside></div><section class="dst-card"><h3>'.dgs_school_icon('book').' سوابق مطالعات امروز</h3>'.dgs_edu_table_start(array('ردیف','درس','مدت مطالعه','یادداشت','زمان ثبت','عملیات'));foreach($entries as $i=>$a)$out.='<tr><td>'.esc_html(dgs_fa_digits($i+1)).'</td><td>'.esc_html($a->subject?:'درس ثبت‌شده').'</td><td><strong>'.esc_html(dgs_study_duration($a->minutes)).'</strong></td><td>'.esc_html($a->note?:'—').'</td><td>'.esc_html(dgs_fa_digits(substr($a->created_at,11,5))).'</td><td><div class="dst-row-actions"><a class="dst-icon-button" title="ویرایش" aria-label="ویرایش مطالعه" href="'.esc_url(dgs_school_url('study',$year,array('study_edit'=>$a->id))).'">'.dgs_school_icon('edit').'</a>'.dgs_study_form('delete',$year).'<input type="hidden" name="entry_id" value="'.(int)$a->id.'"><input type="hidden" name="revision" value="'.(int)$a->revision.'"><button class="dst-icon-button dst-delete" title="حذف" aria-label="حذف مطالعه" data-dge-confirm="این مطالعه حذف شود؟">'.dgs_study_trash().'</button></form></div></td></tr>';
 $out.='</tbody></table></div>'.(!$entries?'<p class="dst-empty">برای امروز مطالعه‌ای ثبت نکرده‌اید.</p>':'').'</section><section class="dst-card"><div class="dst-section-heading"><div><h3>'.dgs_school_icon('chart').' مجموع مطالعه هفتگی</h3><p>از شنبه تا جمعه؛ روز بدون ثبت با صفر نمایش داده می‌شود</p></div><span class="dst-week-pill">مجموع هفته: '.esc_html(dgs_study_duration(array_sum(array_column($week,'minutes')))).'</span></div>'.dgs_study_bars($week).'</section>'.dgs_study_month_history($uid,$year);$fb=dgs_study_feedback($uid,$year);if($fb)$out.='<section class="dst-card dst-feedback-read"><h3>بازخورد مشاور · '.esc_html($fb->counselor).'</h3><p>'.nl2br(esc_html($fb->message)).'</p><small>آخرین ثبت: '.esc_html(dgs_fa_digits(dgs_att_jdate(substr($fb->updated_at,0,10)).' '.substr($fb->updated_at,11,5))).'</small></section>';return $out.'</div>';
}
function dgs_study_trash(){return '<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M3 6h18M8 6V3h8v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/></svg>';}
function dgs_study_class_options($year){if(!current_user_can('dgs_manage_education')&&!dgs_edu_role(get_current_user_id(),'dgs_counselor'))return array();global $wpdb;$e=dgs_edu_tables();$args=array($year);$scope='';if(!current_user_can('dgs_manage_education')){$scope=" AND EXISTS(SELECT 1 FROM {$e['counseling']} a WHERE a.student_id=en.student_id AND a.school_year=en.school_year AND a.counselor_id=%d)";$args[]=get_current_user_id();}$rows=$wpdb->get_results($wpdb->prepare("SELECT DISTINCT c.* FROM {$e['classes']} c JOIN {$e['enrollments']} en ON en.class_id=c.id WHERE en.school_year=%s $scope ORDER BY c.grade,c.id",$args));return dgs_edu_class_options($rows);}
function dgs_study_staff($year){
 $manager=current_user_can('dgs_manage_education');$filters=array('grade'=>absint(dgs_att_get('study_grade')),'class'=>absint(dgs_att_get('study_class')),'search'=>sanitize_text_field(dgs_att_get('study_search')));$total=dgs_study_roster($year,$filters,0,true);$page=max(1,min(max(1,(int)ceil($total/20)),absint(dgs_att_get('study_page','1'))));$rows=dgs_study_roster($year,$filters,($page-1)*20);$selected=absint(dgs_att_get('study_student'));$explicit=$selected>0;if(!$selected&&$rows)$selected=(int)$rows[0]->ID;$class=$selected?dgs_study_student_class($selected,$year):null;$accessible=$class&&dgs_study_can_read($selected,$year);$out='<div class="dsp-school dst-study dst-counselor">'.dgs_school_title($manager?'گزارش مطالعه دانش‌آموزان':'دانش‌آموزان من','مدیریت و پیگیری وضعیت تحصیلی و مطالعه دانش‌آموزان'.($manager?' مدرسه':' تحت مشاوره')).'<section class="dst-filter"><form method="get" action="'.esc_url(dgs_page_url('portal')).'"><input type="hidden" name="dg_tab" value="study"><input type="hidden" name="dg_year" value="'.esc_attr($year).'">'.dgs_edu_select('study_grade','پایه',array(10=>'دهم',11=>'یازدهم',12=>'دوازدهم'),$filters['grade'],false).dgs_edu_select('study_class','کلاس',dgs_study_class_options($year),$filters['class'],false).'<label class="dst-search">جست‌وجوی نام دانش‌آموز<input name="study_search" value="'.esc_attr($filters['search']).'" maxlength="100" placeholder="جست‌وجوی نام دانش‌آموز…"></label><button class="dg-btn">جست‌وجو</button></form></section><section class="dst-card dst-roster">'.dgs_edu_table_start(array('ردیف','نام و نام خانوادگی','پایه','کلاس','میانگین تحصیلی','ساعات مطالعه هفتگی','تکالیف معوق'));
 foreach($rows as $i=>$r){$series=dgs_study_grade_series($r->ID,$year);$week=dgs_study_week($r->ID,$year);$pending=count(dgs_study_tasks($r->ID,$year,200,true));$url=dgs_school_url('study',$year,array('study_grade'=>$filters['grade'],'study_class'=>$filters['class'],'study_search'=>$filters['search'],'study_page'=>$page,'study_student'=>$r->ID));$out.='<tr '.((int)$r->ID===$selected?'class="dst-selected"':'').'><td>'.esc_html(dgs_fa_digits(($page-1)*20+$i+1)).'</td><td><a href="'.esc_url($url).'#dst-student">'.esc_html($r->display_name).'</a></td><td>'.esc_html(dgs_edu_grade_label($r->grade)).'</td><td>'.esc_html(dgs_edu_class_label($r)).'</td><td>'.esc_html($series?dgs_school_number($series[0]->average,2):'—').'</td><td>'.esc_html(dgs_study_duration(array_sum(array_column($week,'minutes')))).'</td><td><span class="dst-pending '.($pending?'has-pending':'').'">'.esc_html(dgs_fa_digits($pending)).($pending>=200?' +':'').'</span></td></tr>';}
 $out.='</tbody></table></div>'.(!$rows?'<p class="dst-empty">دانش‌آموزی با این فیلتر پیدا نشد.</p>':'').'<nav class="dge-pagination">';foreach(array(-1=>'قبلی',1=>'بعدی') as $step=>$label)if($page+$step>0&&$page+$step<=ceil($total/20))$out.='<a href="'.esc_url(dgs_school_url('study',$year,array('study_grade'=>$filters['grade'],'study_class'=>$filters['class'],'study_search'=>$filters['search'],'study_page'=>$page+$step))).'">'.$label.'</a>';$out.='<span>'.esc_html(dgs_fa_digits($page)).'</span></nav><p class="dst-help">میانگین آخرین ماه منتشرشده؛ تکالیف معوق شامل مهلت‌گذشته‌های ارسال‌نشده یا نیازمند اصلاح کلاس فعلی است.</p></section>';
 if($explicit&&!$accessible)return $out.'<p class="dge-error">این دانش‌آموز در سال انتخابی تحت دسترسی شما نیست.</p></div>';if(!$accessible)return $out.'</div>';$u=get_userdata($selected);$week=dgs_study_week($selected,$year,true);$series=dgs_study_grade_series($selected,$year);$fb=dgs_study_feedback($selected,$year);$out.='<section class="dst-student-detail" id="dst-student"><header class="dst-student-header"><h2>'.dgs_school_icon('users').' '.esc_html($u->display_name).'</h2><p>پایه: '.esc_html(dgs_edu_grade_label($class->grade)).' | کلاس: '.esc_html(dgs_edu_class_label($class)).'</p></header><div class="dst-two"><section class="dst-card"><h3>'.dgs_school_icon('chart').' روند میانگین تحصیلی</h3>'.dgs_school_line_chart($series).'</section><section class="dst-card"><h3>'.dgs_school_icon('book').' مطالعه روزانه (۷ روز اخیر)</h3>'.dgs_study_bars($week).'</section></div><div class="dst-detail-bottom"><section class="dst-card dst-feedback"><h3>'.dgs_school_icon('edit').' بازخورد مشاور</h3>';
 if(!$manager&&dgs_edu_role(get_current_user_id(),'dgs_counselor')&&dgs_study_assigned($selected,$year))$out.=dgs_study_form('feedback',$year).'<input type="hidden" name="student_id" value="'.$selected.'"><input type="hidden" name="revision" value="'.($fb?(int)$fb->revision:0).'"><label class="screen-reader-text" for="dst-message">بازخورد مشاور</label><textarea id="dst-message" name="message" maxlength="4000" rows="8" required placeholder="بازخورد خود را برای دانش‌آموز بنویسید…">'.esc_textarea($fb?$fb->message:'').'</textarea><button class="dg-btn">'.dgs_school_icon('edit').' ثبت / ویرایش بازخورد</button><p class="dst-help">این بازخورد در صفحه مطالعه دانش‌آموز نمایش داده می‌شود.</p></form>';else $out.='<p class="dst-feedback-read">'.($fb?nl2br(esc_html($fb->message)):'بازخوردی از مشاور فعلی ثبت نشده است.').'</p>';$out.='</section><section class="dst-card dst-homework"><h3>'.dgs_school_icon('book').' تکالیف (فایل‌ها)</h3>'.dgs_edu_table_start(array('ردیف','عنوان تکلیف','تاریخ ارسال / مهلت','وضعیت','عملیات'));$tasks=dgs_study_tasks($selected,$year);foreach($tasks as $i=>$a){$submitted=(bool)$a->submission_id;$status=$submitted?($a->status==='revision'?'نیاز به اصلاح':'تحویل‌شده'):'تحویل نشده';$file=$submitted?dgs_hw_submission($a->submission_id):null;$out.='<tr><td>'.esc_html(dgs_fa_digits($i+1)).'</td><td>'.esc_html($a->title).'</td><td>'.esc_html(dgs_fa_digits(dgs_att_jdate(wp_date('Y-m-d',$submitted?(int)$a->submitted_at:(int)$a->due_at,wp_timezone())))).'</td><td><span class="dst-task-state '.($submitted&&$a->status!=='revision'?'is-sent':'').'">'.esc_html($status).'</span></td><td>'.($file&&dgs_hw_can_read($file)?'<a class="dst-view-file" href="'.esc_url(dgs_hw_url($year,array('hw_submission'=>$file->id))).'">مشاهده</a>':'—').'</td></tr>';}$out.='</tbody></table></div>'.(!$tasks?'<p class="dst-empty">تکلیفی برای این کلاس ثبت نشده است.</p>':'').'<p class="dst-help">۱۰ تکلیف آخر؛ مشاهده فایل فقط در محدوده مجاز گیرنده و نقش شماست.</p></section></div></section>';
 return $out.'</div>';
}
function dgs_edu_view_study($year){return dgs_study_portal($year);}
function dgs_study_portal($year){if(get_option('dgs_study_schema')!=='1')return '<p class="dge-error">جدول مطالعه هنوز آماده نیست.</p>';if(dgs_edu_role(get_current_user_id(),'dgs_student')&&!current_user_can('dgs_manage_education'))return dgs_study_student($year);if(current_user_can('dgs_manage_education')||dgs_edu_role(get_current_user_id(),'dgs_counselor'))return dgs_study_staff($year);return '';}
function dgs_study_page_active(){return dgs_is_role_portal()&&(dgs_portal_tab()==='study'||(dgs_edu_role(get_current_user_id(),'dgs_counselor')&&in_array(dgs_portal_tab(),array('overview','students'),true)));}
add_action('wp_enqueue_scripts',function(){if(!dgs_study_page_active())return;wp_add_inline_style('dgs-school-panels',file_get_contents(DGS_PATH.'assets/study.css'));},30);
add_action('template_redirect',function(){if(dgs_study_page_active())nocache_headers();});
